function licenseKeyFormatting(s, k) {
  const result = [];
  let count = 0;

  for (let i = s.length - 1; i >= 0; i--) {
    const ch = s[i];
    if (ch === '-') {
      continue;
    }
    if (count === k) {
      result.push('-');
      count = 0;
    }
    result.push(ch.toUpperCase());
    count++;
  }
  return result.reverse().join('');
}

