function licenseKeyFormatting(s, k) {
  // Strip dashes, then cut a short first group followed by full groups from the left.
  const clean = s.split('-').join('').toUpperCase();
  if (clean === '') return '';
  const first = clean.length % k || k;
  const groups = [clean.slice(0, first)];
  for (let at = first; at < clean.length; at += k) groups.push(clean.slice(at, at + k));
  return groups.join('-');
}

