function generate(rand, size) {
  const alnum = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const pickChar = () => alnum[Math.floor(rand() * alnum.length)];
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 12);
    const dashRate = rand() < 0.15 ? 0.9 : rand() * 0.5;
    let s = '';
    for (let i = 0; i < n; i++) s += rand() < dashRate ? '-' : pickChar();
    const k = rand() < 0.1 ? 10000 : 1 + Math.floor(rand() * 5);
    return [s, k];
  }
  const choices = [1, 2, 3, 4, 5, 8, 37, 1000, 10000];
  const k = choices[Math.floor(rand() * choices.length)];
  const total = 10000;
  // Keep the formatted key within 10,000 characters: m letters plus about m / k dashes.
  const m = Math.min(total, Math.floor((total * k) / (k + 1)));
  const chars = Array.from({ length: total }, (_, i) => (i < m ? pickChar() : '-'));
  for (let i = chars.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return [chars.join(''), k];
}
